import copy,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
HERE=Path(__file__).resolve().parent
DAY='2026-10-25'
G=json.loads((ROOT/'historiography-1920-2000.json').read_text())
assert G['revision_history'][-1]['version']=='1.169'
assert next(p for p in G['people'] if p['id']=='sarah_carter').get('node_id') is None
assert 'sarah_carter' not in {n['id'] for n in G['nodes']}

def write(path,value):
 p=HERE/path;p.parent.mkdir(exist_ok=True,parents=True);p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def source(suffix,title,url,note,status='bibliographic_metadata_checked'):
 return dict(id='sc170_'+suffix,title=title,citation=title,url=url,verification=dict(status=status,checked_on=DAY,note=note))
def event(suffix,label,year,source_ids,support,kind='publication',track='contributions'):
 return dict(id='sc170_'+suffix,label=label,kind=kind,track=track,date=dict(year=year,precision='year'),source_ids=['graph:'+s for s in source_ids],support=support)

